    var piv=col; for(var r=col+1;r<n;r++) if(Math.abs(M[r][col])>Math.abs(M[piv][col])) piv=r;
    var t=M[col]; M[col]=M[piv]; M[piv]=t; var tb=bb[col]; bb[col]=bb[piv]; bb[piv]=tb;
    var d=M[col][col]||1e-9;
    for(var r=0;r<n;r++){ if(r===col) continue; var f=M[r][col]/d; for(var c=col;c<n;c++) M[r][c]-=f*M[col][c]; bb[r]-=f*bb[col]; }
  }
  var x=[]; for(var i=0;i<n;i++) x.push(bb[i]/(M[i][i]||1e-9)); return x;
}
